(function validateSprachdoktorModules(modules){
  const ids=new Set(),questions=new Set();
  const all=modules.flatMap(module=>module[4]);
  if(all.length!==360)throw new Error(`Der Fundus muss genau 360 Aufgaben enthalten; gefunden: ${all.length}.`);
  for(const item of all){
    if(!item.id||ids.has(item.id))throw new Error(`Doppelte Aufgaben-ID: ${item.id}`);ids.add(item.id);
    for(const field of ["instruction","q","answer","why","tip"])if(!String(item[field]??"").trim())throw new Error(`Aufgabe ${item.id}: ${field} fehlt.`);
    if(item.opts?.length||item.kind==="Auswählen")throw new Error(`Multiple Choice ist nicht erlaubt: ${item.id}`);
    const key=`${item.instruction}||${item.q}`.normalize("NFC").replace(/\s+/g," ").trim().toLocaleLowerCase("de-CH");
    if(questions.has(key))throw new Error(`Doppelte Aufgabe: ${item.id}`);questions.add(key);
    if(/vollständigen Satz/i.test(item.instruction)&&String(item.answer).trim().split(/\s+/).length<3)throw new Error(`Keine vollständige Satzlösung: ${item.id}`);
  }
})(window.sprachdoktorModules);

